import express from "express"
const router = express.Router()
interface User { id: string; name: string; email: string; createdAt: Date }
const users: User[] = [
  { id: "1", name: "Alice", email: "alice@example.com", createdAt: new Date("2024-01-01") },
  { id: "2", name: "Bob", email: "bob@example.com", createdAt: new Date("2024-01-02") },
]
router.get("/", (req, res) => res.json({ users, total: users.length }))
router.get("/:id", (req, res) => {
  const user = users.find(u => u.id === req.params.id)
  if (!user) return res.status(404).json({ error: "User not found" })
  res.json(user)
})
router.post("/", (req, res) => {
  const { name, email } = req.body
  if (!name || !email) return res.status(400).json({ error: "name and email required" })
  const newUser: User = { id: String(Date.now()), name, email, createdAt: new Date() }
  users.push(newUser)
  res.status(201).json(newUser)
})
export default router

```

