import express from "express"
const router = express.Router()
interface Post { id: string; userId: string; title: string; body: string; createdAt: Date }
const posts: Post[] = [
  { id: "1", userId: "1", title: "Hello World", body: "My first post", createdAt: new Date() },
]
router.get("/", (req, res) => {
  const { userId } = req.query
  const result = userId ? posts.filter(p => p.userId === userId) : posts
  res.json({ posts: result, total: result.length })
})
router.get("/:id", (req, res) => {
  const post = posts.find(p => p.id === req.params.id)
  if (!post) return res.status(404).json({ error: "Post not found" })
  res.json(post)
})
router.post("/", (req, res) => {
  const { userId, title, body } = req.body
  if (!userId || !title || !body) return res.status(400).json({ error: "userId, title, and body required" })
  const newPost: Post = { id: String(Date.now()), userId, title, body, createdAt: new Date() }
  posts.push(newPost)
  res.status(201).json(newPost)
})
export default router

```

